package com.projexa.coaching.students.entity;
import jakarta.persistence.*; import java.time.LocalDate; import java.util.UUID;
@Entity @Table(name="students") public class Student { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(nullable=false) private UUID tenantId; @Column(nullable=false) private String admissionNumber; @Column(nullable=false) private String firstName; private String lastName,email,phone,gender,address,profilePhotoUrl; private LocalDate dateOfBirth; private String status="ACTIVE"; public UUID getId(){return id;} public UUID getTenantId(){return tenantId;} public void setTenantId(UUID v){tenantId=v;} public String getAdmissionNumber(){return admissionNumber;} public void setAdmissionNumber(String v){admissionNumber=v;} public String getFirstName(){return firstName;} public void setFirstName(String v){firstName=v;} public String getLastName(){return lastName;} public void setLastName(String v){lastName=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} public String getPhone(){return phone;} public void setPhone(String v){phone=v;} public LocalDate getDateOfBirth(){return dateOfBirth;} public void setDateOfBirth(LocalDate v){dateOfBirth=v;} public String getGender(){return gender;} public void setGender(String v){gender=v;} public String getAddress(){return address;} public void setAddress(String v){address=v;} public String getProfilePhotoUrl(){return profilePhotoUrl;} public void setProfilePhotoUrl(String v){profilePhotoUrl=v;} public String getStatus(){return status;} public void setStatus(String v){status=v;} }